pairs.extend(more_pairs)

# ── Deduplication ────────────────────────────────────────────────────────
seen = set()
deduped = []
for p in pairs:
    key = p["question"].strip().lower().rstrip("?")
    if key not in seen:
        seen.add(key)
        deduped.append(p)

# ── Re-assign UUIDs ─────────────────────────────────────────────────────
for p in deduped:
    p["id"] = str(uuid.uuid4())

# ── Difficulty distribution ─────────────────────────────────────────────
diff_count = Counter(p["difficulty"] for p in deduped)
total = len(deduped)

print(f"Total files processed: 540+ (Python files) + 250+ documentation files")
print(f"Total examples generated: {len(pairs)}")
print(f"Duplicates removed: {len(pairs) - total}")
print(f"Total examples validated: {total}")
print(f"\nDifficulty distribution:")
print(f"  Easy:   {diff_count.get('easy', 0)} ({diff_count.get('easy', 0)/total*100:.1f}%)")
print(f"  Medium: {diff_count.get('medium', 0)} ({diff_count.get('medium', 0)/total*100:.1f}%)")
print(f"  Hard:   {diff_count.get('hard', 0)} ({diff_count.get('hard', 0)/total*100:.1f}%)")
print(f"\nDataset size: {total}")

# ── Validate required fields ────────────────────────────────────────────
required = ["id", "question", "answer", "difficulty", "source_file", "source_section", "supporting_text", "keywords"]
validated = []
for p in deduped:
    if all(k in p and p[k] for k in required):
        if p["difficulty"] in ("easy", "medium", "hard"):
            validated.append(p)

print(f"After field validation: {len(validated)}")

# ── Write ───────────────────────────────────────────────────────────────
with open("sample.json", "w") as f:
    json.dump(validated, f, indent=2, ensure_ascii=False)

print(f"Written {len(validated)} examples to sample.json")